package com.gameaggregator.contractservice.domain;import jakarta.persistence.*;import java.time.LocalDate;import java.util.UUID;@Entity @Table(name="contract_versions",uniqueConstraints=@UniqueConstraint(columnNames={"contractId","versionNumber"})) public class ContractVersion{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID contractId;@Column(nullable=false)public int versionNumber;@Column(nullable=false)public LocalDate effectiveDate;public LocalDate expirationDate;@Lob @Column(nullable=false)public String territoriesJson;@Lob @Column(nullable=false)public String gameRightsJson;@Lob @Column(nullable=false)public String revenueAgreementJson;public String attachmentKey;@Column(nullable=false)public String status="DRAFT";public UUID approvedBy;protected ContractVersion(){}public ContractVersion(UUID c,int v,LocalDate e,LocalDate x,String t,String g,String r,String a){contractId=c;versionNumber=v;effectiveDate=e;expirationDate=x;territoriesJson=t;gameRightsJson=g;revenueAgreementJson=r;attachmentKey=a;}}